1	import React from 'react';
2	import { Box, Image } from '@salesforce/retail-react-app/app/components/shared/ui';
3	import { ContentfulLivePreview } from '@contentful/live-preview';
4	import type { ContentfulAsset, Hotspot } from '../../../types/contentful';
5	import HotspotMarker from './hotspotMarker';
6	
7	type ShoppableImageProps = {
8	  /** @cf Image, media */
9	  image?: string | ContentfulAsset;
10	  /** @cf Image Alt Text */
11	  imageAlt?: string;
12	  /** @cf Hotspots (JSON) */
13	  hotspots?: string;
14	  entryId?: string;
15	  locale?: string;
16	};
17	
18	const parseHotspots = (raw: string | undefined): Hotspot[] => {
19	  if (!raw) return [];
20	  try {
21	    const parsed = JSON.parse(raw);
22	    if (!Array.isArray(parsed)) return [];
23	    return parsed.filter(
24	      (h): h is Hotspot =>
25	        typeof h === 'object' &&
26	        h !== null &&
27	        typeof h.x === 'number' &&
28	        typeof h.y === 'number' &&
29	        typeof h.productId === 'string' &&
30	        h.productId.length > 0,
31	    );
32	  } catch {
33	    return [];
34	  }
35	};
36	
37	const resolveImageUrl = (image: string | ContentfulAsset | undefined): string => {
38	  if (!image) return '';
39	  if (typeof image === 'string') return image;
40	  const url = image.fields.file.url;
41	  return url.startsWith('//') ? `https:${url}` : url;
42	};
43	
44	const resolveImageAlt = (image: string | ContentfulAsset | undefined, fallback?: string): string => {
45	  if (!image || typeof image === 'string') return fallback ?? '';
46	  return image.fields.title ?? fallback ?? '';
47	};
48	
49	/** @cf-register */
50	const ShoppableImage = ({ image, imageAlt, hotspots, entryId, locale = 'en-US' }: ShoppableImageProps) => {
51	  const inspectorProps = entryId ? ContentfulLivePreview.getProps({ entryId, fieldId: 'image', locale }) : {};
52	  const parsedHotspots = parseHotspots(hotspots);
53	  const src = resolveImageUrl(image);
54	  const alt = imageAlt ?? resolveImageAlt(image);
55	
56	  return (
57	    <Box position="relative" w="100%" {...inspectorProps}>
58	      <Image src={src} alt={alt} w="100%" display="block" loading="lazy" />
59	      {parsedHotspots.map((hotspot, i) => (
60	        <HotspotMarker key={i} x={hotspot.x} y={hotspot.y} productId={hotspot.productId} />
61	      ))}
62	    </Box>
63	  );
64	};
65	
66	export default ShoppableImage;
