1	import React from 'react';
2	import { Box, Image, Link, Skeleton, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
3	import { useProduct } from '@salesforce/commerce-sdk-react';
4	import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
5	import { proxyImageUrl } from '../../../utils/sfccImage';
6	
7	type HotspotPopupProps = {
8	  productId: string;
9	};
10	
11	const HotspotPopup = ({ productId }: HotspotPopupProps) => {
12	  const { data: product, isLoading } = useProduct(
13	    { parameters: { id: productId, allImages: true } },
14	    { enabled: !!productId },
15	  );
16	
17	  if (!isLoading && !product) return null;
18	
19	  const image = product?.imageGroups?.find((g) => g.viewType === 'small')?.images?.[0];
20	  const price = product?.price;
21	
22	  return (
23	    <Box w="180px">
24	      <Skeleton isLoaded={!isLoading}>
25	        {image && (
26	          <Image
27	            src={proxyImageUrl(image.disBaseLink ?? image.link ?? '')}
28	            alt={image.alt ?? product?.name ?? ''}
29	            w="100%"
30	            h="120px"
31	            objectFit="cover"
32	            loading="lazy"
33	            mb={2}
34	          />
35	        )}
36	      </Skeleton>
37	      <Skeleton isLoaded={!isLoading} mb={1}>
38	        <Text fontSize="sm" fontWeight="medium" noOfLines={2}>
39	          {product?.name ?? ''}
40	        </Text>
41	      </Skeleton>
42	      {price != null && (
43	        <Skeleton isLoaded={!isLoading} mb={2}>
44	          <Text fontSize="sm" color="gray.600">
45	            ${price.toFixed(2)}
46	          </Text>
47	        </Skeleton>
48	      )}
49	      <Skeleton isLoaded={!isLoading}>
50	        <Link
51	          href={productUrlBuilder({ id: productId })}
52	          fontSize="xs"
53	          fontWeight="semibold"
54	          textDecoration="underline"
55	          display="block"
56	        >
57	          Shop Now
58	        </Link>
59	      </Skeleton>
60	    </Box>
61	  );
62	};
63	
64	export default HotspotPopup;
