1	import React from 'react';
2	import {
3	  Box,
4	  Popover,
5	  PopoverArrow,
6	  PopoverBody,
7	  PopoverContent,
8	  PopoverTrigger,
9	} from '@salesforce/retail-react-app/app/components/shared/ui';
10	import { keyframes } from '@chakra-ui/react';
11	import HotspotPopup from './hotspotPopup';
12	
13	type HotspotMarkerProps = {
14	  x: number;
15	  y: number;
16	  productId: string;
17	};
18	
19	const pulseRing = keyframes`
20	  0%   { transform: scale(1);   opacity: 0.6; }
21	  70%  { transform: scale(2);   opacity: 0; }
22	  100% { transform: scale(1);   opacity: 0; }
23	`;
24	
25	const MARKER_SIZE = '16px';
26	
27	const HotspotMarker = ({ x, y, productId }: HotspotMarkerProps) => (
28	  <Box position="absolute" left={`${x}%`} top={`${y}%`} transform="translate(-50%, -50%)" zIndex={1}>
29	    <Popover isLazy placement="top" trigger="hover">
30	      <PopoverTrigger>
31	        <Box position="relative" w={MARKER_SIZE} h={MARKER_SIZE} cursor="pointer">
32	          {/* Pulse ring */}
33	          <Box
34	            position="absolute"
35	            inset={0}
36	            borderRadius="full"
37	            bg="white"
38	            opacity={0.6}
39	            animation={`${pulseRing} 1.8s ease-out infinite`}
40	          />
41	          {/* Solid dot */}
42	          <Box position="absolute" inset={0} borderRadius="full" bg="white" boxShadow="0 0 0 2px rgba(0,0,0,0.25)" />
43	        </Box>
44	      </PopoverTrigger>
45	      <PopoverContent w="auto" border="none" boxShadow="lg" p={3}>
46	        <PopoverArrow />
47	        <PopoverBody p={0}>
48	          <HotspotPopup productId={productId} />
49	        </PopoverBody>
50	      </PopoverContent>
51	    </Popover>
52	  </Box>
53	);
54	
55	export default HotspotMarker;
