6	type DuplexSectionProps = {
7	  duplexSection: ContentfulRichText;
8	  entryId?: string;
9	  locale?: string;
10	};
11	
12	const renderRichText = (richText: ContentfulRichText): React.ReactNode => {
13	  if (!richText.content || richText.content.length === 0) {
14	    return null;
15	  }
16	
17	  return richText.content.map((node, index) => {
18	    if (node.nodeType === 'text' && node.value) {
19	      const text = node.value;
20	      if (node.marks && node.marks.length > 0) {
21	        const markTypes = node.marks.map((mark) => mark.type);
22	        if (markTypes.includes('bold')) {
23	          return <strong key={index}>{text}</strong>;
24	        }
25	        if (markTypes.includes('italic')) {
26	          return <em key={index}>{text}</em>;
27	        }
28	      }
29	      return text;
30	    }
31	
32	    if (node.nodeType === 'paragraph' && node.content) {
33	      return (
34	        <Text key={index} mb={4}>
35	          {renderRichText({ nodeType: 'document', data: {}, content: node.content })}
36	        </Text>
37	      );
38	    }
39	
40	    if (node.nodeType === 'heading-1' && node.content) {
41	      return (
42	        <Text as="h1" key={index} fontSize="4xl" fontWeight="bold" mb={4}>
43	          {renderRichText({ nodeType: 'document', data: {}, content: node.content })}
44	        </Text>
45	      );
46	    }
47	
48	    if (node.nodeType === 'heading-2' && node.content) {
49	      return (
50	        <Text as="h2" key={index} fontSize="3xl" fontWeight="bold" mb={4}>
51	          {renderRichText({ nodeType: 'document', data: {}, content: node.content })}
52	        </Text>
53	      );
54	    }
55	
56	    return null;
57	  });
58	};
59	
