61	  const inspectorProps = entryId ? ContentfulLivePreview.getProps({ entryId, fieldId: 'duplexSection', locale }) : {};
62	
63	  return (
64	    <Box padding={8} maxWidth="container.xl" marginX="auto" {...inspectorProps}>
65	      {renderRichText(duplexSection)}
66	    </Box>
67	  );
68	};
