1	#!/usr/bin/env node
2	/**
3	 * Contentful content-type sync script.
4	 *
5	 * Usage:
6	 *   npm run sync:contentful
7	 *
8	 * Reads CONTENTFUL_MANAGEMENT_TOKEN, CONTENTFUL_SPACE_ID, and
9	 * CONTENTFUL_ENVIRONMENT_ID from the environment (loaded via --env-file in
10	 * the npm script). Each file in ./content-types/ defines one content type.
11	 * The script upserts (creates or updates) each content type and publishes it.
12	 *
13	 * To register a new component:
14	 *   1. Add a new file to scripts/contentful/content-types/
15	 *   2. Run:  npm run sync:contentful
16	 */
17	
18	'use strict';
19	
20	const contentfulManagement = require('contentful-management');
21	const path = require('path');
22	const fs = require('fs');
23	
24	/**
25	 * @typedef {Object} FieldDefinition
26	 * @property {string} id
27	 * @property {string} name
28	 * @property {string} type
29	 * @property {string} [linkType]
30	 * @property {boolean} [required]
31	 * @property {Record<string, unknown>} [defaultValue]
32	 * @property {string} [helpText]
33	 * @property {Array<Record<string, unknown>>} [validations]
34	 */
35	
36	/**
37	 * @typedef {Object} ContentTypeDefinition
38	 * @property {string} id
39	 * @property {string} name
40	 * @property {string} [displayField]
41	 * @property {string} [description]
42	 * @property {FieldDefinition[]} fields
43	 */
44	
45	const REQUIRED_ENV = ['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID', 'CONTENTFUL_ENVIRONMENT_ID'];
46	
47	function checkEnv() {
48	  const missing = REQUIRED_ENV.filter((k) => !process.env[k]);
49	  if (missing.length) {
50	    console.error(`\n❌  Missing env vars: ${missing.join(', ')}`);
51	    console.error('   Add them to .env (at repo root) and re-run.\n');
52	    process.exit(1);
53	  }
54	}
55	
56	/**
57	 * Build the field payload accepted by the Contentful Management API.
58	 * @param {FieldDefinition} def
59	 */
60	function buildField(def) {
61	  /** @type {Record<string, unknown>} */
62	  const field = {
63	    id: def.id,
64	    name: def.name,
65	    type: def.type,
66	    required: def.required ?? false,
67	    localized: false,
68	    validations: def.validations ?? [],
69	  };
70	  if (def.linkType) field.linkType = def.linkType;
71	  if (def.defaultValue) field.defaultValue = def.defaultValue;
72	  return field;
73	}
74	
75	/**
76	 * Upsert a single content type: create if absent, update fields if present.
77	 * Uses the contentful-management v10+ plain client API.
78	 * @param {import('contentful-management').PlainClientAPI} client
79	 * @param {ContentTypeDefinition} def
80	 */
81	async function upsertContentType(client, def) {
82	  let ct;
83	  let isNew = false;
84	
85	  try {
86	    ct = await client.contentType.get({ contentTypeId: def.id });
87	  } catch (err) {
88	    if (err.name !== 'NotFound') throw err;
89	    isNew = true;
90	  }
91	
92	  const fields = def.fields.map(buildField);
93	
94	  if (isNew) {
95	    ct = await client.contentType.createWithId(
96	      { contentTypeId: def.id },
97	      {
98	        name: def.name,
99	        displayField: def.displayField,
100	        description: def.description ?? '',
101	        fields,
102	      },
103	    );
104	    console.log(`  ✅  Created  "${def.id}"`);
105	  } else {
106	    const defIds = new Set(def.fields.map((f) => f.id));
107	    ct.fields = [
108	      // Preserve existing fields not in the definition
109	      ...(ct.fields ?? []).filter((f) => !defIds.has(f.id)),
110	      // Upsert defined fields
111	      ...fields,
112	    ];
113	    ct.name = def.name;
114	    if (def.displayField) ct.displayField = def.displayField;
115	    if (def.description !== undefined) ct.description = def.description;
116	    ct = await client.contentType.update({ contentTypeId: def.id }, ct);
117	    console.log(`  ♻️   Updated  "${def.id}"`);
118	  }
119	
120	  await client.contentType.publish({ contentTypeId: def.id }, ct);
121	  console.log(`  📢  Published "${def.id}"`);
122	}
123	
124	async function main() {
125	  checkEnv();
126	
127	  const client = contentfulManagement.createClient(
128	    { accessToken: process.env.CONTENTFUL_MANAGEMENT_TOKEN },
129	    {
130	      type: 'plain',
131	      defaults: {
132	        spaceId: process.env.CONTENTFUL_SPACE_ID,
133	        environmentId: process.env.CONTENTFUL_ENVIRONMENT_ID,
134	      },
135	    },
136	  );
137	
138	  const defsDir = path.join(__dirname, 'content-types');
139	  const files = fs
140	    .readdirSync(defsDir)
141	    .filter((f) => f.endsWith('.js'))
142	    .sort();
143	
144	  if (!files.length) {
145	    console.log('No content type definitions found in scripts/contentful/content-types/');
146	    return;
147	  }
148	
149	  for (const file of files) {
150	    const def = /** @type {ContentTypeDefinition} */ (require(path.join(defsDir, file)));
151	    console.log(`→ Processing "${def.id}" (${file})`);
152	    await upsertContentType(client, def);
153	  }
154	
155	  console.log('\n✅  Sync complete.\n');
156	}
157	
158	main().catch((err) => {
159	  console.error('\n❌  Sync failed:', err.message ?? err);
160	  process.exit(1);
161	});
