2	/**
3	 * Contentful Studio Experiences component definition codegen.
4	 *
5	 * Source of truth: @cf JSDoc tags on Props types in experiences/*.tsx
6	 *
7	 * Usage:
8	 *   npm run generate:contentful          — write definitions.ts
9	 *   npm run generate:contentful:check    — diff only; exits non-zero if stale
10	 *
11	 * Author conventions (see .docs/temp/contentfulCodegen.md for full spec):
12	 *   /** @cf-register *\/  — on the default export to opt a file in
13	 *   /** @cf Headline *\/  — required on every non-handler, non-children prop
14	 *   /** @cf Body, longText *\/  — with explicit control override
15	 *   /** @cf skip *\/      — explicitly exclude a prop
16	 *
17	 * Valid controls: shortText | longText | select | toggle | number | media
18	 * Auto-inferred: string→shortText, boolean→toggle, number→number,
19	 *                string-literal union→select
20	 * Auto-skipped:  on* handler props, children (emits children:true instead)
21	 * Fails loudly:  any untagged non-handler, non-children prop
22	 */
23	
24	import { Project, SyntaxKind } from 'ts-morph';
25	import { readdirSync, writeFileSync, readFileSync, mkdtempSync } from 'fs';
26	import { join, basename, dirname } from 'path';
