1	/**
2	 * Migration 001 — Initial content types with locale support.
3	 *
4	 * Applies the shoppableImage content type with correct localization settings.
5	 * Translatable fields (title, imageAlt) get localized: true.
6	 * Structural fields (image, hotspots) get localized: false — product IDs
7	 * and asset references are consistent across locales.
8	 *
9	 * This migration supersedes the legacy sync.js upsert which set localized: false
10	 * on all fields. Running both is safe — the migration's field definitions win
11	 * because they are applied after sync.js.
12	 */
13	
14	export const id = '001-initial-content-types';
15	
16	/** @param {import('contentful-management').PlainClientAPI} client */
17	export async function up(client, { environmentId }) {
18	  const contentTypeId = 'shoppableImage';
19	
20	  const fields = [
21	    { id: 'title',    name: 'Title',           type: 'Symbol', required: true,  localized: true,  validations: [] },
22	    { id: 'image',    name: 'Image',            type: 'Link',   required: true,  localized: false, linkType: 'Asset', validations: [] },
23	    { id: 'imageAlt', name: 'Image Alt Text',   type: 'Symbol', required: false, localized: true,  validations: [] },
24	    { id: 'hotspots', name: 'Hotspots',         type: 'Object', required: false, localized: false, validations: [] },
25	  ];
26	
27	  let ct;
28	  let isNew = false;
29	
30	  try {
31	    ct = await client.contentType.get({ environmentId, contentTypeId });
32	  } catch (err) {
33	    if (err.name !== 'NotFound') throw err;
34	    isNew = true;
35	  }
36	
37	  if (isNew) {
38	    ct = await client.contentType.createWithId(
39	      { environmentId, contentTypeId },
40	      {
41	        name: 'Shoppable Image',
42	        displayField: 'title',
43	        description: 'An editorial image with product hotspots. Each hotspot links to an SFCC product.',
44	        fields,
45	      },
46	    );
47	  } else {
48	    // Merge: preserve any fields not in this definition, update the ones that are
49	    const definedIds = new Set(fields.map((f) => f.id));
50	    ct.fields = [
51	      ...(ct.fields ?? []).filter((f) => !definedIds.has(f.id)),
52	      ...fields,
53	    ];
54	    ct.displayField = 'title';
55	    ct = await client.contentType.update({ environmentId, contentTypeId }, ct);
56	  }
57	
58	  await client.contentType.publish({ environmentId, contentTypeId }, ct);
59	}
